import * as W from './world.js';
import {Renderer,transform,project,V} from './engine.js';
import {makeScene,channelGeometry,channelPoint,drawPerson,PEOPLE,PLACES,OBSTACLES,C} from './scene.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='awe-first-orchard-v08';
let world=W.genesis(),player={x:0,z:16,y:0,vy:0,angle:Math.PI,bank:'near'},saved=false,saveWarning=false;
try{const raw=localStorage.getItem(SAVE);if(raw&&raw.length<150000){const s=JSON.parse(raw);world=W.validateSave(s.world);if(s.player&&Number.isFinite(s.player.x)&&Number.isFinite(s.player.z)&&W.walkable(world,s.player.x,s.player.z))player={...player,x:s.player.x,z:s.player.z,angle:Number.isFinite(s.player.angle)?s.player.angle:Math.PI,bank:s.player.z<-19?'far':'near'};saved=true;}}catch{world=W.genesis();saveWarning=true;}
let started=false,panel=null,previousFocus=null,keys={},near=null,atlas=false,yaw=0,pitch=.46,distance=12,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,sound=false,audioCtx=null,lastPulseTime=-10,toastTimer,discoveryTimer,previewMesh=null,previewPlan=null,proposal=null,channelMesh=null,lastChannelSignature='',camera=[13,17,35],target=[0,2,-9],pet={x:1,z:17,angle:0},game=null,lockedByOtherTab=false;
let renderer,meshes;try{renderer=new Renderer($('world'));meshes=makeScene(renderer);}catch(e){$('fatal').hidden=false;$('fatal').textContent=e.message;$('enter').disabled=true;throw e;}
if(saved){$('enter').innerHTML='Return to your world <span>↗</span>';$('arrival').querySelector('.arrival-note').textContent='Your crossing, channels and discoveries are waiting.';}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200);}
function save(){if(lockedByOtherTab)return;try{localStorage.setItem(SAVE,JSON.stringify({world,player:{x:player.x,z:player.z,angle:player.angle},savedAt:Date.now()}));}catch{if(!saveWarning){toast('This browser could not save your world. Export it from the journal before leaving.');saveWarning=true;}}}
function mutate(fn){try{if(lockedByOtherTab)throw Error('Reload to continue the world saved in the other tab.');fn();save();updateHUD();rebuildChannels();return true;}catch(e){toast(e.message);return false;}}
function tone(freq,duration=.3,gain=.045,delay=0){if(!sound||!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),at=audioCtx.currentTime+delay;o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(gain,at+.015);g.gain.exponentialRampToValueAtTime(.0001,at+Math.max(.04,duration));o.connect(g);g.connect(audioCtx.destination);o.start(at);o.stop(at+duration+.05);}
function townScore(){for(const[s,i]of W.SINKS.map((s,i)=>[s,i])){let n=world.deliveries[s];if(n)tone([220,330,440][i],n/6,.06,i*.24);}}
function toggleSound(){sound=!sound;if(sound){audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();townScore();}updateHUD();}
function doPulse(){lastPulseTime=performance.now()/1000;if(mutate(()=>W.pulse(world))){rescuePlayer();townScore();toast(W.bridgeOpen(world)?'The rain moves. The living crossing is open.':'The rain moves. The crossing needs six stored water.');}}
function rescuePlayer(){if(!W.walkable(world,player.x,player.z)){player.x=0;player.z=player.bank==='far'?-21:-5;player.y=0;player.vy=0;toast('The bridge folded. Your safety thread returned you to the bank you came from.');}}
function rebuildChannels(){const sig=JSON.stringify(world.channels);if(sig===lastChannelSignature)return;lastChannelSignature=sig;if(channelMesh)renderer.dispose(channelMesh);channelMesh=renderer.mesh(channelGeometry(world.channels));}
function clearPreview(){if(previewMesh)renderer.dispose(previewMesh);previewMesh=null;previewPlan=null;}
function enter(){started=true;$('arrival').hidden=true;$('hud').hidden=false;if(saveWarning)toast('A previous save could not be restored. This is a fresh local world.');else toast(saved?'Welcome back. Your world remembers.':'WASD to wander. Drag to look. Q opens the water loom.');updateHUD();save();}
function setPanel(title,kicker,html,kind='other'){previousFocus=document.activeElement;keys={};panel=kind;$('panel-title').textContent=title;$('panel-kicker').textContent=kicker;$('panel-body').innerHTML=html;$('panel').hidden=false;$('panel-scrim').hidden=false;$('interaction').hidden=true;$('close-panel').focus();}
function closePanel(){if(lockedByOtherTab&&panel==='locked')return;panel=null;keys={};$('panel').hidden=true;$('panel-scrim').hidden=true;clearPreview();if(previousFocus instanceof HTMLElement)previousFocus.focus();}
function bind(id,fn){$(id)?.addEventListener('click',fn);}
function needsTable(storage=world.storage){return `<table class="facts">${W.SINKS.map(s=>`<tr><td>${s==='habitat'?'Reed garden':s==='bridge'?'Crossing':'Orchard'}</td><td>${storage[s]} / ${s==='bridge'?6:5} water</td></tr>`).join('')}</table>`;}
function loomSvg(preview=[]){const pos={spring:[180,22],west:[80,80],east:[280,80],bridge:[180,156],orchard:[310,156],habitat:[50,156]};return `<svg class="loom-map" viewBox="0 0 360 190" aria-label="Water channel topology">${Object.values(world.channels).map(c=>`<line x1="${pos[c.from][0]}" y1="${pos[c.from][1]}" x2="${pos[c.to][0]}" y2="${pos[c.to][1]}"/>`).join('')}${preview.map(([a,b])=>`<line class="preview" x1="${pos[a][0]}" y1="${pos[a][1]}" x2="${pos[b][0]}" y2="${pos[b][1]}"/>`).join('')}${Object.entries(pos).map(([k,[x,y]])=>`<circle cx="${x}" cy="${y}" r="7"/><text x="${x}" y="${y+23}" text-anchor="middle">${k==='habitat'?'reeds':k}</text>`).join('')}</svg>`;}
function loom(kind='installed'){
 clearPreview();setPanel(kind==='temporary'?'Weave the rain':'The water loom',kind==='temporary'?'WEAVE · A TEMPORARY CONNECTION':'SHAPE · A LASTING CONNECTION',`<p>The same rain feeds a bridge, an orchard and a reed garden. Give it a path; then <strong>Pulse</strong> to let it through.</p><div id="loom-diagram">${loomSvg()}</div><div class="button-row"><button id="loom-installed" class="outline-button">Lasting · fiber</button><button id="loom-temporary" class="outline-button">3 rains · Focus</button></div>${Object.keys(world.channels).length===0?'<div class="callout"><h4 style="margin-top:0">A gift: the Mercy Braid</h4><p>Two interwoven paths share balanced rain equally. Preview the full six-channel design for 24 fiber.</p><button id="braid-preview" class="outline-button">Preview the Mercy Braid ↗</button></div>':''}<div class="split"><div class="field"><label for="from-node">From</label><select id="from-node"><option value="spring">Wellspring</option><option value="west">West loom</option><option value="east">East loom</option></select></div><div class="field"><label for="to-node">To</label><select id="to-node"></select></div></div><div class="field"><label for="capacity">Channel capacity · cost per unit</label><select id="capacity">${[2,4,6,1,3,5].map(c=>`<option value="${c}" ${c===4?'selected':''}>${c} water · ${c} ${kind==='temporary'?'Focus':'fiber'}</option>`).join('')}</select></div><button id="preview-channel" class="primary-button">Preview this connection</button><div id="forecast"></div><button id="loom-pulse" class="outline-button">Pulse · move the rain</button><p class="panel-note">You have ${world.fiber.human} fiber and ${world.focus.human} Focus. Temporary weaving lasts exactly three rain evaluations. Closing this panel resumes walking; rain moves only when you choose.</p><h3>Installed in this world</h3>${Object.entries(world.channels).length?Object.entries(world.channels).map(([key,c])=>`<div class="channel-row"><span>${c.from} → ${c.to}<small>capacity ${c.capacity} · ${c.owner==='agent'?'Serein':'you'} · ${c.kind==='temporary'?c.remaining+' rains left':'lasting'}</small></span>${c.owner==='human'?`<button data-salvage="${key}">${c.kind==='temporary'?'Dismiss':'Salvage '+Math.floor(c.capacity/2)}</button>`:'<small>Partner-owned</small>'}</div>`).join(''):'<p class="panel-note">No channels yet. The first thread is yours.</p>'}`,'loom');
 const destinations=()=>{$('to-node').innerHTML=($('from-node').value==='spring'?['west','east']:W.SINKS).map(n=>`<option value="${n}">${n==='habitat'?'Reed garden':n}</option>`).join('');};destinations();$('from-node').addEventListener('change',destinations);
 bind('loom-installed',()=>loom('installed'));bind('loom-temporary',()=>loom('temporary'));bind('loom-pulse',()=>{doPulse();loom(kind);});bind('braid-preview',()=>showForecast(W.BRAID,'installed'));bind('preview-channel',()=>showForecast([[$('from-node').value,$('to-node').value,Number($('capacity').value)]],kind));
 document.querySelectorAll('[data-salvage]').forEach(b=>b.onclick=()=>{if(mutate(()=>W.removeChannel(world,b.dataset.salvage)))loom(kind);});
}
function showForecast(plan,kind){try{const clone=structuredClone(world);for(const[a,b,c]of plan)W.channel(clone,a,b,c,kind);W.pulse(clone);clearPreview();previewPlan={plan:structuredClone(plan),kind,revision:world.revision};previewMesh=renderer.mesh(channelGeometry(Object.fromEntries(plan.map(([from,to,capacity])=>[from+'>'+to,{from,to,capacity}])) ,true));$('loom-diagram').innerHTML=loomSvg(plan);$('forecast').innerHTML=`<div class="callout"><h4 style="margin-top:0">After the next ${world.weather} rain</h4>${needsTable(clone.storage)}<p>${plan.length} connection${plan.length>1?'s':''} · ${plan.reduce((n,p)=>n+p[2],0)} ${kind==='temporary'?'Focus':'fiber'}. No resources spent yet.</p><button id="accept-preview" class="primary-button">Make this ${kind==='temporary'?'weave':'design'} real</button><button id="cancel-preview" class="outline-button">Cancel preview</button></div>`;bind('cancel-preview',()=>loom(kind));bind('accept-preview',()=>{const p=previewPlan;if(mutate(()=>{if(!p||p.revision!==world.revision)throw Error('The world changed. Preview again.');const c=structuredClone(world);for(const[a,b,n]of p.plan)W.channel(c,a,b,n,p.kind);world=c;})){tone(523,.45);toast('The threads are real. Pulse to guide the rain through them.');loom(kind);}});}catch(e){toast(e.message);}}
function companion(){setPanel('Serein','A PARTNER, BY INVITATION',`<p>“You needn’t finish the world alone. Tell me where to leave room for you.”</p><p>Serein can propose a small repair using its own ${world.fiber.agent} fiber. You see the exact connections and their predicted effect before they become real.</p><label class="check-row"><input id="grant-agent" type="checkbox" ${world.grant.enabled?'checked':''}>Invite Serein to build</label><label class="check-row"><input id="reserve-bridge" type="checkbox" ${world.reserveBridge?'checked':''}>Leave both bridge inlets for me</label><button id="ask-agent" class="primary-button" ${world.grant.enabled?'':'disabled'}>Ask for a proposal</button><div id="agent-proposal"></div><p class="panel-note">Serein is a disclosed, bounded scripted planner in this simulator. It cannot change your water priorities, take your channels, spend your fiber or advance the rain. Its installed channels remain its own after permission is withdrawn.</p>`,'agent');$('grant-agent').onchange=e=>{mutate(()=>W.grant(world,e.target.checked));proposal=null;companion();};$('reserve-bridge').onchange=e=>{mutate(()=>W.reserve(world,e.target.checked));proposal=null;companion();};bind('ask-agent',()=>{try{proposal=W.propose(world);$('agent-proposal').innerHTML=`<div class="callout"><h4 style="margin-top:0">“I can help the ${proposal.target==='habitat'?'reeds':proposal.target}.”</h4><p>${proposal.plan.map(([a,b,c])=>`${a} → ${b}, capacity ${c}`).join('<br>')}</p><p>${proposal.plan.reduce((n,p)=>n+p[2],0)} of Serein’s fiber. Predicted storage after your next rain:</p>${needsTable(proposal.forecast)}<button id="accept-agent" class="primary-button">Accept this exact proposal</button></div>`;bind('accept-agent',()=>{if(mutate(()=>W.acceptProposal(world,proposal))){toast('Serein installed the connections you approved.');companion();}});}catch(e){toast(e.message);}});}
function speak(id){if(id==='serein')return companion();const content={iria:{title:'Iria',kicker:'THE BRIDGEWRIGHT',text:'“A perfect bridge is only a bridge. Give the rain a second destination, and it becomes a neighborhood.”',body:'The crossing stands when it holds six water. Each pulse adds routed rain, then loses two. Its planks and your passage obey the same threshold.',button:'Show me the water loom',action:()=>loom()},vey:{title:'Vey',kicker:'THE CARAVAN KEEPER',text:world.cargo.status==='delivered'?'“We made the crossing. The next question is what we leave growing behind us.”':'“Four bundles. One crossing. I’ll take the wagon through when the wood can hold us.”',body:`The wagon is ${world.cargo.status}. All four food travel with it. ${world.escrow?'Twelve Marks are reserved until it physically reaches the far depot.':'It reached the depot; the carrier received the reserved twelve Marks.'}`,button:'Inspect the delivery',action:()=>journal()},oru:{title:'Oru',kicker:'KEEPER OF SMALL THINGS',text:world.storage.habitat>=5?'“Listen. The reeds still have a voice.”':'“The bridge is loud when it wakes. The reeds are quiet when they need you.”',body:`The reeds hold ${world.storage.habitat} water. They flourish at five. Their note in the town’s melody comes only from rain that really reaches them.`,button:'Listen to the town',action:()=>{if(!sound)toggleSound();townScore();toast('Crossing: 220 Hz. Orchard: 330 Hz. Reeds: 440 Hz. Dry deliveries are silent.');}}}[id];if(!content)return;setPanel(content.title,content.kicker,`<p style="font:24px/1.5 Georgia;color:#ecdfbe">${content.text}</p><p>${content.body}</p><button id="dialogue-action" class="primary-button">${content.button}</button><button id="dialogue-leave" class="outline-button">Until next time</button>`,'dialogue');bind('dialogue-action',content.action);bind('dialogue-leave',closePanel);}
function inspectNode(id){const n=W.NODES[id];if(id==='spring'||id==='west'||id==='east')return loom();setPanel(n.name,'LISTEN · THE MATERIAL TRUTH',`<p>${id==='bridge'?(W.bridgeOpen(world)?'The pale wood is carrying its own weight. You and Vey share this same passage.':'The living wood has folded into the cleft. It needs six stored water to support the crossing.'):id==='orchard'?'The fruit is a sign of the orchard’s condition. Harvesting is not enabled in this slice.':'The reeds bend toward the water they actually received.'}</p>${needsTable()}<p>Last rain delivered ${world.deliveries[id]} here. Water remains between pulses. Temporary channels disappear after their third evaluation; their stored water does not.</p><button id="node-loom" class="primary-button">Tend the water paths</button><button id="node-song" class="outline-button">Hear the last rain</button>`,'inspect');bind('node-loom',()=>loom());bind('node-song',()=>{if(!sound)toggleSound();townScore();});}
function journal(){const l=W.ledger(world);setPanel('The Unwritten','A HISTORY OF WHAT HAPPENED',`<p>The world remembers accepted changes. Its recent record contains facts, not invented gratitude.</p><div class="button-row"><button id="export-world" class="outline-button">Export this world ↓</button><button id="open-agent" class="outline-button">Serein’s invitation</button></div><h3>The carrier’s ledger</h3><table class="facts"><tr><td>Wagon</td><td>${world.cargo.status}</td></tr><tr><td>Food · title</td><td>4 · ${world.cargo.owner}</td></tr><tr><td>Reserved commission</td><td>${world.escrow} Marks</td></tr><tr><td>Carrier received</td><td>${world.balances.carrier} Marks</td></tr><tr><td>All money · conserved</td><td>${l.money} / 50</td></tr><tr><td>Water accounting residual</td><td>${l.water}</td></tr></table><h3>Places remembered · ${world.discovered.length}/4</h3><p>${PLACES.map(p=>`${world.discovered.includes(p.id)?'✧':'○'} ${p.name}`).join('<br>')}</p><h3>Recent history</h3>${[...world.events].reverse().slice(0,32).map(e=>`<div class="history-entry"><span>RAIN ${e.pulse} · EVENT ${e.id}</span><p>${esc(e.text)}</p></div>`).join('')}<p class="panel-note">This local slice retains the latest 160 events. Its save is a state snapshot, not a complete replay proof or an on-chain record.</p>`,'journal');bind('open-agent',companion);bind('export-world',()=>{const blob=new Blob([JSON.stringify({profile:W.PROFILE,world,player},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='AWE-First-Orchard-world.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
function settings(){setPanel('Make yourself at home','WORLD SETTINGS',`<p>Walk, build and explore at your own pace. Rain moves only when you press Pulse. Panels, the pavilion and a hidden browser tab pause physical travel.</p><div class="field"><label for="weather">Rain on the next pulse</label><select id="weather">${['balanced','drought','storm'].map(n=>`<option ${world.weather===n?'selected':''} value="${n}">${n[0].toUpperCase()+n.slice(1)} · ${n==='balanced'?12:n==='drought'?6:18} water</option>`).join('')}</select></div><div class="field"><label for="priority">First claim when rain is scarce</label><select id="priority">${W.SINKS.map(n=>`<option ${world.priority[0]===n?'selected':''} value="${n}">${n==='habitat'?'Reed garden':n==='bridge'?'Crossing':'Orchard'}</option>`).join('')}</select></div><label class="check-row"><input id="reduce-motion" type="checkbox" ${reduced?'checked':''}>Reduce ambient motion</label><label class="check-row"><input id="audio-setting" type="checkbox" ${sound?'checked':''}>Sound on</label><h3>Your four verbs</h3><table class="facts"><tr><td>WASD / arrows</td><td>Move</td></tr><tr><td>Drag · scroll</td><td>Look · zoom</td></tr><tr><td>Space · Shift</td><td>Jump · run</td></tr><tr><td>Q · B</td><td>Weave · Shape</td></tr><tr><td>F · E</td><td>Pulse · Listen</td></tr><tr><td>M · J · Escape</td><td>Atlas · journal · close</td></tr></table><div class="button-row"><button id="about" class="outline-button">About this simulator</button><button id="reset-start" class="outline-button">Begin a fresh world</button></div><div id="reset-confirm"></div>`,'settings');$('weather').onchange=e=>mutate(()=>W.setWeather(world,e.target.value));$('priority').onchange=e=>mutate(()=>W.setPriority(world,e.target.value));$('reduce-motion').onchange=e=>reduced=e.target.checked;$('audio-setting').onchange=toggleSound;bind('about',about);bind('reset-start',()=>{$('reset-confirm').innerHTML='<div class="callout"><p>This replaces this browser’s saved world. Export your current world from the journal first if you want to keep its record.</p><button id="reset-confirmed" class="primary-button">Start a new experiment</button></div>';bind('reset-confirmed',()=>{world=W.genesis();player={x:0,z:16,y:0,vy:0,angle:Math.PI,bank:'near'};pet={x:1,z:17,angle:0};proposal=null;lockedByOtherTab=false;closePanel();mutate(()=>{});toast('A fresh orchard. A new possibility.');});});}
function about(){setPanel('A world that answers','AWE · THE FIRST ORCHARD',`<p>This is the first embodied slice of the AWE design: an inhabited fantasy world for human players and invited AI partners.</p><p>Explore a 3D landscape, guide a conserved water network, grow a traversable bridge, follow a physical delivery, listen to material consequences, and play a little game in the bell pavilion.</p><h3>What is real here</h3><p>The channels, resource costs, water allocation, bridge access, wagon position, one finite payment, local history, partner permissions and Raincatch input are running systems.</p><h3>What comes next</h3><p>This is a single-player browser simulator. Serein uses a scripted planner. Live multiplayer, language-model agents, production combat, civilization simulation and crypto settlement are design directions, not running services here.</p><p>No wallet is needed. No token, sale or financial return is offered. The world saves locally in this browser; clearing browser data removes it.</p><p class="panel-note">Embodied ruleset ${W.PROFILE}. It preserves the previous rain arithmetic but replaces abstract cargo qualification with physical arrival. This exploratory world has no delivery deadline or twelve-pulse ending. Raincatch is a new local pavilion variant, not the previous deterministic protocol port.</p><button id="about-close" class="primary-button">${started?'Back to the orchard':'Close and enter the world'}</button>`,'about');bind('about-close',closePanel);}
function inspect(){if(near){if(near.type==='person')speak(near.id);else if(near.type==='node')inspectNode(near.id);else if(near.id==='pavilion')pavilionIntro();else if(near.id==='archive')journal();else if(near.id==='orchard')inspectNode('orchard');else if(near.id==='overlook'){setPanel('The Sleeper’s Ear','LISTEN · A WORLD BENEATH THE WORLD','<p style="font:25px/1.5 Georgia;color:#e7dcbe">The mountain exhales.</p><p>Far beyond the roofs, a pale horn shifts against the dawn. The city has grown on a creature so old that its next step belongs to another age.</p><p>The living world starts with small, legible consequences: rain in a reed bed; a route that can hold a wagon; a song with a missing voice.</p><button id="overlook-song" class="primary-button">Listen to this place</button>','inspect');bind('overlook-song',()=>{if(!sound)toggleSound();tone(55,2,.06);tone(82.4,2,.03,.5);});}}else{toast('Walk toward a person, a loom stone or a landmark, then press E to listen.');}}
function updateHUD(){for(const s of W.SINKS){$(s+'-meter').style.width=(world.storage[s]/10*100)+'%';$(s+'-value').textContent=world.storage[s]+' / '+(s==='bridge'?6:5);$(s+'-meter').style.background=world.storage[s]>=(s==='bridge'?6:5)?'var(--green)':'var(--amber)';}$('fiber').textContent=world.fiber.human;$('focus').textContent=world.focus.human;$('weather-label').textContent='Dawn · '+world.weather[0].toUpperCase()+world.weather.slice(1)+' rain';$('pulse-label').textContent='Rain '+world.pulse;$('sound').textContent=sound?'♫':'♪';$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('sound').title=sound?'Mute sound':'Enable sound';let title,copy,action;if(world.cargo.status==='delivered'){title=world.storage.orchard>=5&&world.storage.habitat>=5?'A neighborhood, alive.':'What grows after victory?';copy=world.storage.orchard>=5&&world.storage.habitat>=5?'The wagon arrived. The orchard and reeds are thriving. There is still a world to wander.':'The wagon arrived. Now listen for the orchard and reed garden’s missing voices.';action='Read what the world remembers';}else if(W.bridgeOpen(world)){title='Walk over your own idea.';copy='The crossing is open. Follow Vey’s wagon to the far bank, or tend the other living places.';action='Listen to the shared world';}else if(Object.keys(world.channels).length){title='Wake the living wood.';copy='Press F to send rain through your paths. The crossing needs six stored water.';action='Let the rain through';}else{title='Give the rain a path.';copy='Connect the spring to the crossing. The old wood is waiting for water.';action='Open the water loom';}$('quest-title').textContent=title;$('quest-copy').textContent=copy;$('quest-action').innerHTML=action+' <span>↗</span>';}
function toggleAtlas(){atlas=!atlas;toast(atlas?'Atlas lens · the same world, seen from above. WASD still moves your character.':'Back in your own footsteps.');}
function pavilionIntro(){setPanel('Catch a little wonder','THE BELL PAVILION',`<p>Raincatch is a 45-second game of attention. Move a bowl beneath the falling notes. Catch amber notes; let pale rain pass.</p><div class="callout"><p>Amber: +1 note.<br>Pale rain: −1 note, never below zero.<br>Missed notes carry no penalty.</p></div><p>Use the arrow keys, A / D, or drag across the screen. Your body stays at the pavilion while you play. No currency or items are created.</p><p class="panel-note">Your best here: ${world.pavilionBest} notes. This is a local solo activity.</p><button id="start-raincatch" class="primary-button">Play Raincatch</button>`,'pavilion');bind('start-raincatch',startGame);}
function startGame(){if(Math.hypot(player.x-24,player.z-15)>7){toast('Walk into the bell pavilion to play.');return;}closePanel();keys={};game={elapsed:0,spawn:0,notes:[],score:0,bowl:.5,seed:54387,done:false};$('raincatch').hidden=false;$('hud').hidden=true;$('game-result').hidden=true;$('leave-game').focus();}
function leaveGame(){game=null;keys={};$('raincatch').hidden=true;$('hud').hidden=false;save();updateHUD();}
function gameRandom(){game.seed=(game.seed*1664525+1013904223)>>>0;return game.seed/4294967296;}
function tickGame(dt){if(!game)return;const canvas=$('rain-game'),ctx=canvas.getContext('2d'),w=innerWidth,h=innerHeight;canvas.width=w;canvas.height=h;if(!game.done){game.elapsed+=dt;game.spawn-=dt;if(keys.a||keys.arrowleft)game.bowl-=dt*.6;if(keys.d||keys.arrowright)game.bowl+=dt*.6;game.bowl=Math.max(.07,Math.min(.93,game.bowl));if(game.spawn<=0){game.spawn=.36+gameRandom()*.22;game.notes.push({x:.07+gameRandom()*.86,y:.23,gold:gameRandom()>.25,speed:.13+gameRandom()*.07});}for(const n of game.notes){const before=n.y;n.y+=dt*n.speed;if(before<.82&&n.y>=.82&&Math.abs(n.x-game.bowl)<.06){game.score=Math.max(0,game.score+(n.gold?1:-1));n.hit=true;if(n.gold)tone([440,523,659,784][game.score%4],.16,.04);}}game.notes=game.notes.filter(n=>n.y<.93&&!n.hit);if(game.elapsed>=45){game.done=true;world.pavilionBest=Math.max(world.pavilionBest,game.score);save();$('game-result').hidden=false;$('game-result').innerHTML=`<p class="eyebrow">A MOMENT WELL CAUGHT</p><h3>${game.score} notes</h3><p>Your best: ${world.pavilionBest}.<br>Only a melody. Nothing to cash out.</p><button class="primary-button" id="play-again">Another little rain</button><button class="outline-button" id="return-world">Return to the orchard</button>`;bind('play-again',startGame);bind('return-world',leaveGame);}}ctx.clearRect(0,0,w,h);ctx.strokeStyle='#c2d6b81a';for(let i=1;i<8;i++){ctx.beginPath();ctx.moveTo(w*i/8,h*.23);ctx.lineTo(w*i/8,h*.85);ctx.stroke();}for(const n of game.notes){ctx.fillStyle=n.gold?'#ebc979':'#a3cbd3';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=n.gold?18:4;ctx.beginPath();ctx.ellipse(n.x*w,n.y*h,n.gold?6:3,n.gold?9:12,0,0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;const bx=game.bowl*w,by=h*.82,bw=Math.max(35,w*.045);ctx.strokeStyle='#ebd7a3';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(bx,by,bw,10,0,0,Math.PI);ctx.stroke();ctx.fillStyle='#dfe2c21a';ctx.beginPath();ctx.ellipse(bx,by+4,bw,14,0,0,Math.PI);ctx.fill();ctx.strokeStyle='#dcdaad44';ctx.beginPath();ctx.moveTo(w*.06,h*.87);ctx.lineTo(w*.94,h*.87);ctx.stroke();$('game-score').textContent=game.score+' notes';$('game-time').textContent=Math.max(0,Math.ceil(45-game.elapsed))+' seconds';}
const labelData=[...PEOPLE.map(p=>({...p,type:'person'})),...Object.entries(W.NODES).map(([id,p])=>({...p,id,type:'node'})),...PLACES.map(p=>({...p,type:'place'}))];
for(const p of labelData){const el=document.createElement('div');el.className='world-label';el.innerHTML=`<i>${p.type==='person'?'◈':p.icon||'◇'}</i>${esc(p.name)}<small>${p.role|| (p.type==='node'?'WATER LOOM':'')}</small>`;el.hidden=true;$('labels').append(el);p.el=el;}
function updateLabels(){near=null;let best=5;for(const p of labelData){let dist=Math.hypot(player.x-p.x,player.z-p.z);if(dist<best){near=p;best=dist;}const screen=project([p.x,p.type==='person'?2.8:3.2,p.z],renderer.vp,innerWidth,innerHeight);const show=started&&!panel&&!game&&screen.visible&&(atlas||dist<21);p.el.hidden=!show;if(show){p.el.style.left=screen.x+'px';p.el.style.top=screen.y+'px';p.el.style.opacity=atlas?'.85':Math.min(1,(23-dist)/9);}}$('interaction').hidden=!near||!!panel||!!game||!started;if(near)$('interact').querySelector('span').textContent=near.id==='pavilion'?'Play Raincatch':near.name;}
function minmap(){const c=$('minimap'),ctx=c.getContext('2d');ctx.clearRect(0,0,220,220);ctx.save();ctx.translate(110,115);ctx.scale(1.65,1.65);ctx.strokeStyle='#e1d9ac18';for(let n=15;n<70;n+=15){ctx.beginPath();ctx.arc(0,0,n,0,Math.PI*2);ctx.stroke();}ctx.fillStyle='#516e5c70';ctx.beginPath();ctx.ellipse(0,14,51,34,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.ellipse(0,-33,37,23,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#0d2b31';ctx.fillRect(-53,-19,106,12);ctx.strokeStyle=W.bridgeOpen(world)?'#efda97':'#9c8061';ctx.lineWidth=W.bridgeOpen(world)?3:1;ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(0,-19);ctx.stroke();ctx.lineWidth=.6;for(const ch of Object.values(world.channels)){const a=W.NODES[ch.from],b=W.NODES[ch.to];ctx.strokeStyle='#8cd1b1';ctx.beginPath();ctx.moveTo(a.x,a.z);ctx.lineTo(b.x,b.z);ctx.stroke();}for(const n of Object.values(W.NODES)){ctx.fillStyle='#d5c99b';ctx.beginPath();ctx.arc(n.x,n.z,1.8,0,7);ctx.fill();}ctx.fillStyle='#d6ae64';ctx.fillRect(world.cargo.x-1.5,world.cargo.z-1.5,3,3);for(const p of PLACES){ctx.strokeStyle=world.discovered.includes(p.id)?'#dfce94':'#8b9c85';ctx.strokeRect(p.x-2,p.z-2,4,4);}ctx.translate(player.x,player.z);ctx.rotate(-player.angle);ctx.fillStyle='#f2f0d6';ctx.beginPath();ctx.moveTo(0,3.7);ctx.lineTo(-2,-2);ctx.lineTo(2,-2);ctx.closePath();ctx.fill();ctx.restore();$('location').textContent=player.z<-19?'THE FAR ORCHARD':W.onBridge(player.x,player.z)?'THE LIVING CROSSING':'THE NEAR BANK';}
function canMove(x,z){return W.walkable(world,x,z)&&!OBSTACLES.some(o=>Math.hypot(x-o.x,z-o.z)<o.r+.32);}
let moving=0,simTime=0,lastSave=0,discoverTick=0;
function step(dt){if(!started||panel||game||lockedByOtherTab)return;simTime+=dt;rescuePlayer();const forward=(keys.w||keys.arrowup?1:0)-(keys.s||keys.arrowdown?1:0),side=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);let dx=side*Math.cos(yaw)-forward*Math.sin(yaw),dz=-side*Math.sin(yaw)-forward*Math.cos(yaw);moving=Math.min(1,Math.hypot(dx,dz));if(moving){const len=Math.hypot(dx,dz),speed=keys.shift?7.2:4.3;dx=dx/len*speed*dt;dz=dz/len*speed*dt;if(canMove(player.x+dx,player.z))player.x+=dx;if(canMove(player.x,player.z+dz))player.z+=dz;const wanted=Math.atan2(dx,dz);let diff=Math.atan2(Math.sin(wanted-player.angle),Math.cos(wanted-player.angle));player.angle+=diff*Math.min(1,dt*14);}if(player.z>=-7)player.bank='near';else if(player.z<=-19)player.bank='far';if(player.y>0||player.vy>0){player.vy-=18*dt;player.y=Math.max(0,player.y+player.vy*dt);if(player.y===0)player.vy=0;}if(W.tickCargo(world,dt)){toast('The wagon arrived. Four food delivered; 12 reserved Marks paid once.');tone(330,.6);tone(440,.7,.045,.25);tone(660,.8,.045,.5);save();updateHUD();}
 const pd=Math.hypot(pet.x-player.x,pet.z-player.z);if(pd>2){const a=Math.atan2(player.x-pet.x,player.z-pet.z),nx=pet.x+Math.sin(a)*dt*Math.min(6,pd),nz=pet.z+Math.cos(a)*dt*Math.min(6,pd);if(W.walkable(world,nx,nz)){pet.x=nx;pet.z=nz;pet.angle=a;}else if(pd>15){pet.x=player.x+1;pet.z=player.z+1;}}discoverTick+=dt;if(discoverTick>.6){discoverTick=0;for(const p of PLACES)if(Math.hypot(player.x-p.x,player.z-p.z)<6&&W.discover(world,p.id,p.name)){$('discovery').hidden=false;$('discovery').querySelector('h2').textContent=p.name;$('discovery').querySelector('p').textContent=p.description;clearTimeout(discoveryTimer);discoveryTimer=setTimeout(()=>$('discovery').hidden=true,4000);tone(660,.5);save();}}if(simTime-lastSave>3){save();lastSave=simTime;}}
function draw(t,dt){const ambient=reduced?0:t;let eyeGoal,targetGoal;if(!started){const a=reduced?.4:.4+Math.sin(t*.025)*.12;eyeGoal=[Math.sin(a)*36,18,Math.cos(a)*36];targetGoal=[0,2,-13];}else if(atlas){eyeGoal=[player.x+7,62,player.z+26];targetGoal=[player.x,0,player.z-5];}else{eyeGoal=[player.x+Math.sin(yaw)*distance*Math.cos(pitch),Math.max(3.3,player.y+2.5+Math.sin(pitch)*distance),player.z+Math.cos(yaw)*distance*Math.cos(pitch)];targetGoal=[player.x,player.y+1.25,player.z];}const speed=1-Math.exp(-dt*(started?7:2));camera=camera.map((v,i)=>v+(eyeGoal[i]-v)*speed);target=target.map((v,i)=>v+(targetGoal[i]-v)*speed);renderer.begin(camera,target,t,atlas);$('sky').style.backgroundPosition=(50+Math.sin(yaw)*24)+'% 50%';renderer.draw(meshes.distant,transform(0,Math.sin(ambient*.23)*.18,0));renderer.draw(meshes.earth);renderer.draw(meshes.architecture);renderer.draw(meshes.green,transform(),{sway:reduced?0:.008});renderer.draw(meshes.orchard,transform(),{tint:world.storage.orchard>=5?[1,1.16,.94]:[.73,.75,.60],sway:reduced?0:.006});renderer.draw(meshes.reeds,transform(),{tint:world.storage.habitat>=5?[1,1.18,1]:[.72,.7,.48],sway:reduced?0:.01});renderer.draw(W.bridgeOpen(world)?meshes.bridge:meshes.closed);
 for(const[id,n]of Object.entries(W.NODES)){let fill=id==='spring'?1.7:W.SINKS.includes(id)?.85*Math.sqrt(world.storage[id]/10):.8;renderer.draw(meshes.water,transform(n.x,.43+Math.sin(ambient*1.2)*.01,n.z,fill,1,fill),{glow:.35,alpha:.82});renderer.draw(meshes.orb,transform(n.x,1.15+Math.sin(ambient*1.5+n.x)*.1,n.z,.8,.8,.8),{glow:.8});}
 if(channelMesh)renderer.draw(channelMesh,transform(),{glow:.18});if(previewMesh)renderer.draw(previewMesh,transform(),{glow:.8,alpha:.65});
 for(const c of Object.values(world.channels)){const flow=world.flows[c.from+'>'+c.to]||0;if(!flow)continue;for(let i=0;i<Math.min(6,flow);i++){const f=((ambient*.18+i/Math.min(6,flow))%1),p=channelPoint(c.from,c.to,f);renderer.draw(meshes.orb,transform(...p,.48,.48,.48),{glow:1.1});}}
 const burst=Math.max(0,1-(t-lastPulseTime)/2);if(burst)for(let i=0;i<28;i++){const a=i*2.4,r=(1-burst)*12;renderer.draw(meshes.orb,transform(player.x+Math.cos(a)*r,player.y+1+Math.sin(a*2)*(1-burst)*3,player.z+Math.sin(a)*r,.6*burst,.6*burst,.6*burst),{glow:1});}
 for(const p of PEOPLE){let px=p.x,pz=p.z;if(p.id==='vey'){px=world.cargo.x+2.4;pz=world.cargo.z+.6;}drawPerson(renderer,meshes,px,W.onBridge(px,pz)&&W.bridgeOpen(world)?.16:0,pz,p.id==='vey'?Math.PI:.4,ambient,p.id==='vey'&&world.cargo.status==='traveling'&&!panel?.65:0,p.color.map(v=>v/.65));}
 renderer.draw(meshes.cart,transform(world.cargo.x,W.onBridge(world.cargo.x,world.cargo.z)&&W.bridgeOpen(world)?.17:.02,world.cargo.z));drawPerson(renderer,meshes,player.x,player.y+(W.onBridge(player.x,player.z)&&W.bridgeOpen(world)?.16:0),player.z,player.angle,ambient,started&&!panel?moving:0);
 renderer.draw(meshes.pet,transform(pet.x,.03+(reduced?0:Math.abs(Math.sin(t*6))*.06),pet.z,1,1,1,pet.angle));
 for(let i=0;i<(reduced?8:38);i++){let x=Math.sin(i*71.1)*39,z=Math.cos(i*31.7)*31,y=1.3+Math.sin(ambient*.5+i)*.8;renderer.draw(meshes.orb,transform(x+Math.sin(ambient*.13+i)*2,y,z+10,.19,.19,.19),{glow:1.2,alpha:.7});}
 for(const p of labelData)if(p.id==='vey'){p.x=world.cargo.x+2.4;p.z=world.cargo.z+.6;}updateLabels();if(started)minmap();}
let last=performance.now()/1000,acc=0;function frame(ms){const t=ms/1000,dt=Math.min(.1,Math.max(0,t-last));last=t;if(!document.hidden){if(game)tickGame(dt);else{acc+=dt;for(let count=0;acc>=1/60&&count<6;count++){step(1/60);acc-=1/60;}draw(t,dt);}}requestAnimationFrame(frame);}
// Input handlers are registered once; panels and activities clear held movement.
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(e.key==='Escape'){if(game)leaveGame();else if(panel)closePanel();else if(started)settings();return;}if(panel){if(e.key==='Tab'){const f=[...$('panel').querySelectorAll('button,input,select,a')].filter(el=>!el.disabled);const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(e.repeat||game||!started)return;if(k===' ')jump();if(k==='q')loom('temporary');if(k==='b')loom();if(k==='f')doPulse();if(k==='e')inspect();if(k==='m')toggleAtlas();if(k==='j')journal();});
window.addEventListener('keyup',e=>delete keys[e.key.toLowerCase()]);window.addEventListener('blur',()=>{keys={};});document.addEventListener('visibilitychange',()=>{keys={};acc=0;last=performance.now()/1000;if(document.hidden)save();});window.addEventListener('pagehide',save);
window.addEventListener('storage',e=>{if(e.key===SAVE&&e.newValue&&started){lockedByOtherTab=true;keys={};setPanel('Your world is open elsewhere','ONE LOCAL WORLD AT A TIME','<p>Another tab changed this saved world. Reload this tab to continue from that snapshot. Movement is paused here to keep the two tabs from overwriting each other.</p><button class="primary-button" id="reload-world">Reload this world</button>','locked');bind('reload-world',()=>location.reload());}});
let drag=null;$('world').addEventListener('pointerdown',e=>{if(!started||panel)return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};$('world').setPointerCapture(e.pointerId);});$('world').addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;yaw-=(e.clientX-drag.x)*.005;pitch=Math.max(.12,Math.min(1.15,pitch+(e.clientY-drag.y)*.004));drag.x=e.clientX;drag.y=e.clientY;});$('world').addEventListener('pointerup',()=>drag=null);$('world').addEventListener('pointercancel',()=>drag=null);$('world').addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(5,Math.min(24,distance+e.deltaY*.015));},{passive:false});
function jump(){if(started&&!panel&&!game&&player.y===0){player.vy=7;tone(165,.12,.015);}}
for(const b of document.querySelectorAll('[data-move]')){b.addEventListener('pointerdown',e=>{e.preventDefault();keys[b.dataset.move]=true;b.setPointerCapture(e.pointerId);});for(const event of['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>delete keys[b.dataset.move]);}
let gameDrag=false;$('rain-game').addEventListener('pointerdown',e=>{gameDrag=true;$('rain-game').setPointerCapture(e.pointerId);if(game)game.bowl=Math.max(.07,Math.min(.93,e.clientX/innerWidth));});$('rain-game').addEventListener('pointermove',e=>{if(game&&gameDrag)game.bowl=Math.max(.07,Math.min(.93,e.clientX/innerWidth));});$('rain-game').addEventListener('pointerup',()=>gameDrag=false);$('rain-game').addEventListener('pointercancel',()=>gameDrag=false);
bind('enter',enter);bind('about-start',about);bind('close-panel',closePanel);bind('panel-scrim',closePanel);bind('home',settings);bind('settings',settings);bind('journal',journal);bind('atlas',toggleAtlas);bind('sound',toggleSound);bind('interact',inspect);bind('touch-jump',jump);bind('leave-game',leaveGame);bind('quest-action',()=>world.cargo.status==='delivered'?journal():W.bridgeOpen(world)?journal():Object.keys(world.channels).length?doPulse():loom());
for(const b of document.querySelectorAll('[data-verb]'))b.onclick=()=>({weave:()=>loom('temporary'),shape:()=>loom(),pulse:doPulse,listen:inspect}[b.dataset.verb]());
$('world').addEventListener('webglcontextlost',e=>{e.preventDefault();save();$('fatal').hidden=false;$('fatal').textContent='The graphics connection was interrupted. Your last world snapshot is saved. Reload this page to return.';});
rebuildChannels();updateHUD();requestAnimationFrame(frame);
